"""Original beginner-first lessons. W3Schools is linked for optional reading, not copied."""
import textwrap
LESSONS=[]
def F(w,title,goal,teach,example,output,walkthrough,starter,answer,tests,hints,topic,mistake,transfer,*,guided=None,packages=None,language='python'):
 i=sum(l['week']==w for l in LESSONS)+1
 clean=lambda s:textwrap.dedent(s).strip()+'\n'
 ex=clean(example);ref=clean(answer)
 # Guided practice keeps the demonstrated example visible and asks a small change.
 LESSONS.append(dict(id=f'f{w:02d}-l{i}',week=w,title=title,goal=goal,teach=teach,example=ex,expectedOutput=output,walkthrough=walkthrough,starter=clean(starter),reference=ref,tests=[dict(label=a,code=b) if isinstance(b,str) else dict(label=a,**b) for a,b in tests],hints=hints,language=language,packages=packages or [],level='guided',minutes=25,commonMistake=mistake,transfer=transfer,guided=guided or dict(prompt='Before the independent task, run the worked example. Change one value, predict the new output, and run it again.',starter=ex),prediction=dict(code=ex,options=[output,'The program always prints nothing','The program must fail'],correct=0,explanation='Trace the walkthrough from top to bottom, then compare the displayed output.'),reflection='In your own words: what changed, why did it work, and which mistake would you check first?',change=transfer,resources=[dict(title='Optional W3Schools topic reading',url='https://www.w3schools.com/python/'+topic+'.asp'),dict(title='Python documentation',url='https://docs.python.org/3/tutorial/')]))
# Week 1: no functions, conditionals or collections required.
F(1,'Your first line of Python','Print I am learning Python on one line.','A program is a set of instructions. Python reads these instructions and performs them. In this lesson you only need one instruction: print.\n\nText must go between matching quotation marks. The parentheses tell print which value to show. The output area is where you see the result; writing code in the editor alone does not run it.','print("My first notebook")','My first notebook',['print is the instruction that displays a value.','The quoted words are text, also called a string.','Run the line and compare the output with the expected output below.'],'# Write one print instruction below.','print("I am learning Python")',[('Exact message',{'outputEquals':'I am learning Python'})],['Start with print.','Put the message in matching quotes.','Use print("I am learning Python").'],'python_intro','Print with a capital P is a different name. Python names are case-sensitive. Use lowercase print.','Change the message to your own learning goal. Explain which characters are Python syntax and which are your text.')
F(1,'Read code from top to bottom','Print Ready and then Go on separate lines.','Python normally runs one statement after another. A statement is one instruction. The order you write matters: printing a title after the answer produces a different screen.\n\nEach print call normally adds a new line. Start with two short statements before trying a large program.','print("Step A")\nprint("Step B")','Step A\nStep B',['The first print finishes before the second starts.','The newline comes from print; you do not need to press Enter inside the quotes.'],'# Print Ready first.\n# Print Go second.','print("Ready")\nprint("Go")',[('Two lines in order',{'outputEquals':'Ready\nGo'})],['Write two print calls.','Each word needs quotes.','Put Ready above Go.'],'python_syntax','Do not split a quoted string over two source lines accidentally. Use two complete print calls.','Swap the two instructions and predict what changes.')
F(1,'Comments explain a decision','Set study_minutes to 20 and print its value. Add a comment explaining the target.','A comment begins with # outside a string. Python ignores the comment when running the program. Comments help a person understand why a decision was made.\n\nThe example also introduces assignment: the name minutes refers to the number 15. Reading print(minutes) asks Python for that value. You will practise variables next.','# A small daily target is easier to repeat.\nminutes = 15\nprint(minutes)','15',['The comment is for the reader.','The equals sign assigns the value on its right to the name on its left.','print(minutes) reads the assigned number.'],'# Explain your target here.\nstudy_minutes = 0\nprint(study_minutes)','''
# Twenty focused minutes is my starting target.
study_minutes = 20
print(study_minutes)
''',[('Target value','assert study_minutes == 20'),('Displayed value',{'outputEquals':'20'})],['Change the number after =.','Keep the variable name study_minutes.','Comments are not printed.'],'python_comments','A # inside quotation marks is part of the text. A # outside them starts a comment.','Write one useful comment about why you picked a study time. Comments are reviewed by you, not automatically scored.')
F(1,'Variables are names for values','Create student_name with the text Asha and semesters_done with the number 1.','A variable lets you name a value and use it again. Choose names that tell a reader what the value means. student_name is more useful than x when storing a name.\n\nUse = to assign. It does not mean a permanent mathematical equality. A later assignment can attach a different value to the same name.','city = "Ahmedabad"\nvisits = 2\nprint(city, visits)','Ahmedabad 2',['city refers to text; visits refers to a number.','The comma in print displays both values with a space.'],'# Create both requested variables.','student_name = "Asha"\nsemesters_done = 1',[('Text value','assert student_name == "Asha"'),('Number value','assert semesters_done == 1 and type(semesters_done) is int')],['Put text in quotes.','Write the number without quotes.','Use one assignment per line.'],'python_variables','student-name is interpreted as subtraction. Use student_name for a name containing two words.','Create a third variable for a goal. Print all three values without changing the original two.')
F(1,'Four useful data types','Create course="Python", days=4, hours=1.5 and enrolled=True.','The type of a value describes what operations make sense. str is text, int is a whole number, float supports decimals, and bool represents True or False.\n\nThe characters "4" make a string. The number 4 is an integer. They look similar on screen but behave differently when you add them. You do not need to memorize every Python type today.','print(type("code"))\nprint(type(3))',"<class 'str'>\n<class 'int'>",['type(value) inspects its type.','The displayed class name tells you whether the value is text or an integer.'],'# Create the four values named in the task.','course = "Python"\ndays = 4\nhours = 1.5\nenrolled = True',[('Text and integer','assert course=="Python" and type(days) is int and days==4'),('Decimal and boolean','assert type(hours) is float and hours==1.5 and enrolled is True')],['course needs quotes; days does not.','Use 1.5 for hours.','True begins with a capital T and has no quotes.'],'python_datatypes','"True" is text; True is a boolean. Do not decide a value’s type only by how it prints.','Use type on your four variables. Explain the difference between days=4 and days="4".')
F(1,'Calculate with numbers','Store 3 notebooks at ₹40 each in total, and the change from ₹200 in change.','Use +, -, * and / for ordinary arithmetic. Python uses * for multiplication. Parentheses group an operation you want to do first.\n\nStore an intermediate result under a useful name so you can inspect it. A calculation is easier to debug when you can check the quantity, price and total separately.','price = 25\nquantity = 2\nbill = price * quantity\nprint(bill)','50',['Read price and quantity first.','Multiplication produces the bill.','Changing quantity recalculates the bill when you rerun the cell.'],'price = 40\nquantity = 3\n# Calculate total and change.','price = 40\nquantity = 3\ntotal = price * quantity\nchange = 200 - total',[('Bill','assert total==120'),('Change','assert change==80')],['Use price * quantity.','Assign the result to total.','Subtract total from 200.'],'python_numbers','Writing 3(40) does not mean multiplication in Python. Use 3 * 40.','Change the quantity to 4. Predict both outputs before running. Restore the task values before checking.')
F(1,'Update a value and trace it','Start points at 5, add 3, then subtract 1. Leave the result in points.','An assignment calculates the right side first. In points = points + 2, Python reads the old points, adds two, then stores the new value.\n\nThe shorter form points += 2 performs this update for a number. Trace each intermediate value on paper instead of guessing the final result.','points = 10\npoints += 2\npoints -= 4\nprint(points)','8',['After line one points is 10.','After line two it is 12.','After line three it is 8.'],'points = 5\n# Add three, then subtract one.','points = 5\npoints += 3\npoints -= 1',[('Final points','assert points==7')],['Use += to add.','Use -= to subtract.','Trace 5 → 8 → 7.'],'python_operators','points =+ 3 assigns positive 3. The update operator is += in that order.','Add a print after each update. Read the trace and explain the final value.')
F(1,'Convert text into a number','Convert quantity_text="3" to an integer and calculate a ₹25-per-item total.','User input and data from text files often arrive as strings. Convert numeric text before doing arithmetic. int("3") produces the integer 3; float("3.5") handles decimals.\n\nConversion can fail if the text is not a number. We will handle that with exceptions later. For now, use the supplied valid text.','age_text = "18"\nage = int(age_text)\nprint(age + 1)','19',['age_text remains a string.','int returns a new numeric value.','Adding one is now arithmetic, not text joining.'],'quantity_text = "3"\n# Make quantity and total.','quantity_text = "3"\nquantity = int(quantity_text)\ntotal = quantity * 25',[('Numeric quantity','assert quantity==3 and type(quantity) is int'),('Total','assert total==75')],['Call int(quantity_text).','Store it in quantity.','Multiply quantity by 25.'],'python_casting','int("3.5") fails because that text is not an integer representation. Use float when the input allows decimals.','In Jupyter, try input("Quantity: ") and convert its returned text. The course quick checker uses supplied inputs for repeatable checks.')
# Week 2: text and decisions, still no custom functions.
F(2,'Read and slice a string','For word="PYTHON", store first="P" and middle="YTH" using indexes and a slice.','A string is an ordered sequence of characters. Index zero refers to the first character. A slice start:stop includes start and excludes stop.\n\nDraw indexes above the word before writing a slice. This makes off-by-one mistakes visible.','word = "CODING"\nprint(word[0])\nprint(word[1:4])','C\nODI',['Index zero selects C.','The slice reads positions 1, 2 and 3, stopping before 4.'],'word = "PYTHON"\n# Assign first and middle.','word = "PYTHON"\nfirst = word[0]\nmiddle = word[1:4]',[('First character','assert first=="P"'),('Middle slice','assert middle=="YTH"')],['Indexes start at zero.','Y begins at index 1.','H is index 3, so stop at 4.'],'python_strings','word[6] fails for a six-character word: the last index is 5.','Find the last character using a negative index. Explain why a slice excludes its stop index.')
F(2,'Clean text without changing the original','Create clean_name="krish" from raw_name="  Krish  ". Keep raw_name unchanged.','A string method is an operation accessed with a dot. strip removes surrounding whitespace. lower converts letters to lowercase.\n\nStrings are immutable: these methods return new strings. You must store the result if you want to use the cleaned value later.','raw = "  Asha  "\nclean = raw.strip().lower()\nprint(clean)','asha',['strip removes the outside spaces.','lower runs on that cleaned result.','raw still refers to the original text.'],'raw_name = "  Krish  "\n# Create clean_name.','raw_name = "  Krish  "\nclean_name = raw_name.strip().lower()',[('Cleaned text','assert clean_name=="krish"'),('Original retained','assert raw_name=="  Krish  "')],['Use .strip().','Then use .lower().','Store the new text under clean_name.'],'python_strings','Calling raw_name.strip() on its own does not update raw_name. Store the returned value.','Try leading spaces, trailing spaces and an already clean name.')
F(2,'Write a readable message with f-strings','Build message="Asha studied 30 minutes." from name and minutes.','An f-string begins with f before the opening quote. Expressions inside braces are evaluated and inserted into the text.\n\nThis keeps the human sentence visible while values can change. Keep spaces and punctuation outside braces intentional.','name = "Sam"\nminutes = 15\nprint(f"{name} studied {minutes} minutes.")','Sam studied 15 minutes.',['The f enables substitution.','Each pair of braces reads a variable.'],'name = "Asha"\nminutes = 30\n# Create message.','name = "Asha"\nminutes = 30\nmessage = f"{name} studied {minutes} minutes."',[('Complete message','assert message=="Asha studied 30 minutes."')],['Start the quoted sentence with f.','Put name and minutes in braces.','End with a full stop.'],'python_strings','Without f, the braces are printed as ordinary characters.','Change minutes and rerun. Compare with joining strings manually using +.')
F(2,'Compare values and understand booleans','With score=40, create passed using >=40 and perfect using ==100.','A comparison produces True or False. >= includes the boundary; > excludes it. Use == to compare two values and = to assign a value.\n\nRead a comparison as a yes/no question. This boolean result will decide which branch runs in the next lesson.','score = 39\nprint(score >= 40)\nprint(score == 100)','False\nFalse',['39 does not reach 40.','39 is not equal to 100.'],'score = 40\n# Create passed and perfect.','score = 40\npassed = score >= 40\nperfect = score == 100',[('Boundary included','assert passed is True'),('Equality check','assert perfect is False')],['Use >= for passed.','Use == for perfect.','Both results should be booleans.'],'python_booleans','score = 100 changes the value. score == 100 checks the value.','Test scores 39, 40 and 100. Make a small table of the two boolean results.')
F(2,'Your first if block and indentation','Start message="Try again". If score=60 is at least 40, change message to "Passed".','An if statement runs an indented block only when its condition is true. The colon introduces the block. Use four spaces consistently at the start of each line inside it.\n\nA notebook helps insert indentation but cannot know which lines you intended to group. A line at the left edge is outside the block.','score = 50\nmessage = "Try again"\nif score >= 40:\n    message = "Passed"\nprint(message)','Passed',['The initial message gives a default.','The condition is True, so the indented assignment runs.','print is outside the block and always runs.'],'score = 60\nmessage = "Try again"\n# Add your if block.','score = 60\nmessage = "Try again"\nif score >= 40:\n    message = "Passed"',[('Correct branch','assert message=="Passed"')],['Write if score >= 40:','Indent the next line four spaces.','Assign message = "Passed" inside the block.'],'python_conditions','A missing colon causes SyntaxError. A block with no indentation causes IndentationError. Read the indicated line and the line just above it.','Set score to 20. Predict whether the indented line runs, then restore 60 for the task.')
F(2,'Choose between two branches','For temperature=35, set advice to "Drink water" when temperature>=30, otherwise "Comfortable".','else gives an alternative when an if condition is false. The if and else keywords align. Each branch has its own indented body.\n\nExactly one branch runs in an if/else pair. Trace the condition first, then ignore the branch that was not selected.','temperature = 22\nif temperature >= 30:\n    advice = "Drink water"\nelse:\n    advice = "Comfortable"\nprint(advice)','Comfortable',['22 >= 30 is False.','Python skips the first body and runs else.'],'temperature = 35\n# Create advice using if and else.','temperature = 35\nif temperature >= 30:\n    advice = "Drink water"\nelse:\n    advice = "Comfortable"',[('Hot-day advice','assert advice=="Drink water"')],['Use if temperature >= 30:.','Align else with if.','Indent the advice assignment inside each branch.'],'python_conditions','Indenting else under the previous assignment breaks the block structure. Align it with its if.','Try temperatures 29, 30 and 35. The boundary 30 should enter the hot branch.')
F(2,'Multiple branches and their order','For score=75, assign grade A for >=80, B for >=60, otherwise C.','elif checks another condition only if earlier conditions were false. Put the more specific or higher boundary first when ranges overlap.\n\nFor score 90, both >=60 and >=80 are true. If >=60 comes first, Python chooses that branch and never checks >=80.','score = 90\nif score >= 80:\n    grade = "A"\nelif score >= 60:\n    grade = "B"\nelse:\n    grade = "C"\nprint(grade)','A',['The first condition succeeds.','The remaining branches are skipped.'],'score = 75\n# Assign grade using the stated rules.','score = 75\nif score >= 80:\n    grade = "A"\nelif score >= 60:\n    grade = "B"\nelse:\n    grade = "C"',[('Middle range','assert grade=="B"')],['Check >=80 first.','Use elif for >=60.','The final else handles remaining values.'],'python_conditions','Several separate if statements can all run. Use an if/elif/else chain when only one category should be chosen.','Trace scores 59, 60, 79 and 80. Explain why the order matters.')
F(2,'Combine conditions with and, or and not','With has_id=True and fee_paid=False, set can_enter only when both are True. Set needs_help when either is False.','and requires both conditions to be true. or needs at least one. not reverses a boolean. Parentheses make a longer decision easier to read.\n\nDescribe the rule in normal words before writing it. Then try all four combinations of two boolean inputs.','has_id = True\nfee_paid = True\nprint(has_id and fee_paid)\nprint(not fee_paid)','True\nFalse',['Both True values make and return True.','not True becomes False.'],'has_id = True\nfee_paid = False\n# Assign can_enter and needs_help.','has_id = True\nfee_paid = False\ncan_enter = has_id and fee_paid\nneeds_help = not has_id or not fee_paid',[('Both required','assert can_enter is False'),('Either missing','assert needs_help is True')],['Use and for entry.','Negate each condition for missing requirements.','Join the missing conditions with or.'],'python_operators','Using or for a rule that requires both conditions grants entry too easily. Translate the words carefully.','Write a four-row truth table and compare it with your program.')
# Week 3: data containers and repetition.
F(3,'A list stores an ordered collection','Make subjects=["Python","Maths"], append "English", and store the first subject in first.','A list groups several values in order. Square brackets create a list. Like strings, list indexes start at zero.\n\nLists are mutable. append changes the existing list by adding one value at the end. Its return value is None, so do not assign the result of append back to the list.','tasks = ["read", "code"]\ntasks.append("test")\nprint(tasks[0])\nprint(len(tasks))','read\n3',['The original list has two items.','append adds a third item.','len counts items, not characters.'],'subjects = ["Python", "Maths"]\n# Append and read the first item.','subjects = ["Python", "Maths"]\nsubjects.append("English")\nfirst = subjects[0]',[('Updated list','assert subjects==["Python","Maths","English"]'),('First item','assert first=="Python"')],['Use subjects.append("English").','Read index zero.','Keep subjects as a list.'],'python_lists','subjects = subjects.append(...) replaces your list with None. Call append as a statement.','Change the second subject by index. Explain the difference between append and index assignment.')
F(3,'Loop over a list one item at a time','Sum the numbers [2,4,6] into total using a loop.','A for loop gives a name to the next item and runs its body for each item. The name changes on each iteration.\n\nAn accumulator stores a result that grows across iterations. Initialize it before the loop. If you reset total inside the loop, you lose earlier work.','total = 0\nfor amount in [3, 5]:\n    total += amount\nprint(total)','8',['Before the loop total is zero.','The first iteration adds three.','The second adds five to the existing three.'],'numbers = [2, 4, 6]\ntotal = 0\n# Add each number.','numbers = [2, 4, 6]\ntotal = 0\nfor number in numbers:\n    total += number',[('Accumulated sum','assert total==12'),('Input retained','assert numbers==[2,4,6]')],['Write for number in numbers:.','Indent total += number.','Keep total=0 before the loop.'],'python_for_loops','Return and break end work early; this script needs neither. Let all iterations finish.','Trace total as 0 → 2 → 6 → 12. Try an empty list and explain the result.')
F(3,'range counts without a written list','Create numbers containing 1 through 5 using range and list.','range(start, stop) represents integers from start up to, but not including, stop. list converts that range into a visible list.\n\nA stop value is a boundary, not the final item. Write the desired first and last numbers before choosing the arguments.','print(list(range(2, 5)))','[2, 3, 4]',['Start at two.','Stop before five.'],'# Create numbers for 1 through 5.','numbers = list(range(1, 6))',[('Inclusive goal, exclusive stop','assert numbers==[1,2,3,4,5]')],['Start at 1.','To include 5, stop at 6.','Wrap range in list.'],'python_for_loops','range(1,5) omits five. This is a common boundary error.','Try range(5) and range(2,10,2). Explain start, stop and step.')
F(3,'A while loop must make progress','Start count at 3 and append 3,2,1 to seen while reducing count to zero.','while repeats as long as its condition remains true. Unlike for, it does not automatically move to a next item. Your body must change the condition eventually.\n\nIf the value never changes, the loop can run forever. Use Stop in the quick runner or restart the notebook kernel when a loop gets stuck.','count = 2\nwhile count > 0:\n    print(count)\n    count -= 1','2\n1',['The condition is checked before every iteration.','Subtracting one makes progress toward zero.'],'count = 3\nseen = []\n# Write the countdown loop.','count = 3\nseen = []\nwhile count > 0:\n    seen.append(count)\n    count -= 1',[('Visited values','assert seen==[3,2,1]'),('Terminating state','assert count==0')],['Loop while count > 0.','Append count before changing it.','Subtract one inside the loop.'],'python_while_loops','A loop body that only prints count never changes count. Add an update.','Predict what happens if you subtract before appending. Compare the two traces.')
F(3,'Tuples and unpacking','Unpack location=("Ahmedabad",380001) into city and postcode.','A tuple groups ordered values that you do not intend to change in place. Parentheses usually make it visible. Unpacking assigns each position to a separate name.\n\nUse a tuple for a small fixed record, such as a coordinate. Use a dictionary when field names will make the data clearer.','point = (4, 7)\nx, y = point\nprint(x + y)','11',['The first value goes to x.','The second goes to y.'],'location = ("Ahmedabad", 380001)\n# Unpack into city and postcode.','location = ("Ahmedabad", 380001)\ncity, postcode = location',[('City','assert city=="Ahmedabad"'),('Postcode','assert postcode==380001')],['Write two names on the left.','Separate them with a comma.','Assign the tuple to them.'],'python_tuples','Unpacking three values into two names raises ValueError. Match the number of positions.','Make a two-value coordinate and unpack it. Try changing a tuple item and read the error.')
F(3,'Sets remove duplicates','Create unique from ["python","web","python"] as a set.','A set stores distinct values. It is useful for membership checks and removing duplicates. A set does not promise the display order you want.\n\nSort a set when a stable presentation order matters. Do not use a set when duplicate items represent meaningful counts.','skills = set(["code", "test", "code"])\nprint(len(skills))','2',['The repeated code value appears once.','len counts distinct values.'],'skills = ["python", "web", "python"]\n# Create unique.','skills = ["python", "web", "python"]\nunique = set(skills)',[('Distinct values','assert unique=={"python","web"}'),('Set type','assert type(unique) is set')],['Use set(skills).','Keep the original list.','Two distinct values remain.'],'python_sets','{} creates an empty dictionary. Use set() for an empty set.','Compare len(skills) and len(unique). Explain what information deduplication removes.')
F(3,'Dictionaries use names instead of positions','Create student with name Asha and score 8; store student["score"] in score.','A dictionary maps keys to values. Keys are useful field names such as name or score. Access a value with its key in square brackets.\n\nThis is easier to read than remembering that position 0 is a name and position 1 is a score. Dictionary keys are unique: assigning an existing key updates that value.','book = {"title": "Python notes", "pages": 12}\nprint(book["pages"])','12',['Each key is followed by a colon and its value.','The lookup uses the exact key pages.'],'# Create student, then read score.','student = {"name":"Asha", "score":8}\nscore = student["score"]',[('Record fields','assert student=={"name":"Asha","score":8}'),('Lookup','assert score==8')],['Use braces with key:value pairs.','Put string keys in quotes.','Read student["score"].'],'python_dictionaries','student[score] looks for the value stored in a variable called score. student["score"] uses the literal key.','Update score to 9 and add a city field. Explain what changes and what stays.')
F(3,'Safe lookups and membership','Read missing stock for eraser using a default of 0; check whether pen is present.','A square-bracket lookup raises KeyError for a missing dictionary key. get(key, default) provides a chosen fallback. Use in to ask whether a key exists.\n\nChoose a fallback that makes sense for the domain. Zero stock is different from missing medical data, so defaults are decisions, not magic fixes.','stock = {"book": 4}\nprint(stock.get("pen", 0))\nprint("book" in stock)','0\nTrue',['The missing key receives the fallback zero.','Membership checks dictionary keys.'],'stock = {"pen": 5}\n# Create erasers and has_pen.','stock = {"pen": 5}\nerasers = stock.get("eraser", 0)\nhas_pen = "pen" in stock',[('Missing default','assert erasers==0'),('Membership','assert has_pen is True')],['Use stock.get("eraser",0).','Use "pen" in stock.','Store the boolean result.'],'python_dictionaries','Testing a value with in on a dictionary checks keys. Use .values() if you truly need to inspect values.','Try a present key with a stored zero. Explain why presence and truthiness are different questions.')
# Week 4: reusable functions only after scripts, blocks, loops and containers.
F(4,'Define and call a function','Define welcome() returning "Ready to learn".','A function gives a name to a reusable piece of work. def defines the function; it does not run the body. A call uses the name followed by parentheses.\n\nreturn sends a value back to the caller. In this exercise the checker calls your function, so you do not need input prompts.','def label():\n    return "Study time"\nprint(label())','Study time',['def creates label.','return is indented inside its body.','label() runs the body; print displays the returned text.'],'def welcome():\n    # Return the requested text.\n    pass','def welcome():\n    return "Ready to learn"',[('Returned value','assert welcome()=="Ready to learn"'),('Repeatable call','assert welcome()==welcome()')],['Keep the function name.','Replace pass with return.','Return a quoted string.'],'python_functions','Writing welcome without parentheses refers to the function itself. welcome() calls it.','Call welcome twice and print both results. Explain definition versus execution.')
F(4,'Parameters carry inputs','Define double(number) returning twice the given number.','A parameter is a name inside a function for a supplied input. An argument is the value supplied at a call. The same function can work with many arguments.\n\nAvoid hard-coding the example answer. Your function should calculate from its parameter so it works for values the lesson did not show.','def triple(value):\n    return value * 3\nprint(triple(4))','12',['value receives four during this call.','The multiplication uses that input.'],'def double(number):\n    pass','def double(number):\n    return number * 2',[('Positive','assert double(5)==10'),('Zero','assert double(0)==0'),('Negative','assert double(-3)==-6')],['Read number inside the body.','Multiply by 2.','Return the result.'],'python_functions','Returning 10 passes the example but fails other inputs. Use the parameter.','Predict double(1.5). Add that as your own test.')
F(4,'Returning is different from printing','Define add(a,b) returning a+b.','print is useful for people reading a screen. return is useful for other code that needs a result. A function that only prints usually returns None.\n\nKeep calculations separate from display. A caller can print a returned result, store it, or use it in another calculation.','def square(n):\n    return n * n\nanswer = square(3)\nprint(answer + 1)','10',['square returns nine.','The caller stores nine and adds one.'],'def add(a, b):\n    print(a + b)  # Change this line.','def add(a, b):\n    return a + b',[('Returned number','assert add(2,3)==5'),('Reusable result','assert add(2,3)*2==10'),('Negative pair','assert add(-2,1)==-1')],['The checker needs a value, not just screen output.','Replace print with return.','Return a+b.'],'python_functions','If you see the correct number printed but the check says None, inspect whether you used return.','Store add(5,7) and multiply it by three without changing the function.')
F(4,'Defaults and keyword arguments','Define greet(name, prefix="Hello") returning prefix, a space and name.','A default argument is used when a caller omits that input. Keyword arguments identify a parameter by name. They make calls with optional settings easier to read.\n\nPut required parameters before defaulted ones. Use simple immutable defaults for now; mutable list defaults are shared between calls and need extra care.','def price(amount, tax=0):\n    return amount + tax\nprint(price(10))\nprint(price(10, tax=2))','10\n12',['The first call uses the default tax zero.','The second explicitly supplies tax two.'],'def greet(name, prefix="Hello"):\n    pass','def greet(name, prefix="Hello"):\n    return f"{prefix} {name}"',[('Default','assert greet("Asha")=="Hello Asha"'),('Keyword override','assert greet("Krish",prefix="Hi")=="Hi Krish"'),('Positional override','assert greet("Sam","Welcome")=="Welcome Sam"')],['Keep the default in the definition.','Use both parameters in the returned text.','Separate them with one space.'],'python_functions','A default is not used when you explicitly pass another value. Distinguish omitted from supplied arguments.','Call greet using both positional and keyword arguments. Explain which is clearer.')
F(4,'Local variables keep work separate','Define discounted(price) using a local final_price equal to 90% of price and returning it.','A variable assigned inside a function is normally local to that call. It helps organize intermediate work without changing unrelated values outside.\n\nPrefer passing inputs and returning outputs over changing global state. That makes functions easier to test and combine.','def after_fee(amount):\n    remaining = amount - 2\n    return remaining\nprint(after_fee(10))','8',['remaining belongs to the function call.','The returned value crosses the function boundary.'],'def discounted(price):\n    pass','def discounted(price):\n    final_price = price * 0.9\n    return final_price',[('Ordinary price','assert discounted(100)==90'),('Zero','assert discounted(0)==0'),('No global variable','assert "final_price" not in globals()')],['Calculate inside the function.','Store the intermediate result in final_price.','Return final_price.'],'python_scope','A local variable is not automatically available after the call. Use the returned value.','Call the function twice with different prices. Explain why the results do not overwrite each other’s local variables.')
F(4,'Combine a loop and a function','Define total_cost(prices) returning their sum, with 0 for an empty list.','A function can contain the loop you already know. Initialize the accumulator inside the function so each call starts fresh.\n\nPlace return after the loop when you want to process every item. An indented return inside the loop exits on the first iteration.','def count_items(items):\n    count = 0\n    for item in items:\n        count += 1\n    return count\nprint(count_items(["pen", "book"]))','2',['The function starts its own counter.','The loop updates it for both items.','return aligns with for, so it runs after the loop.'],'def total_cost(prices):\n    total = 0\n    # Add the prices, then return total.','def total_cost(prices):\n    total = 0\n    for price in prices:\n        total += price\n    return total',[('Many items','assert total_cost([10,20,5])==35'),('Empty','assert total_cost([])==0'),('Fresh call','assert total_cost([2])==2 and total_cost([3])==3')],['Use for price in prices.','Indent only the update inside that loop.','Return after all iterations.'],'python_functions','A return in the first loop iteration skips later prices. Check its indentation.','Draw the indentation levels: function body four spaces, loop body eight spaces.')
F(4,'Debug using expected and actual values','Fix last(items) so it returns the last item or None for an empty list.','Debugging starts with a small example and an expected result. Run the code, compare actual with expected, and locate the earliest wrong assumption.\n\nA boundary case such as an empty list often exposes a hidden assumption. Fix the cause, then rerun both the failing case and a normal case.','items = ["a", "b"]\nprint(items[-1])','b',['Negative index -1 selects the final item.','An empty list has no final item, so it needs a separate decision.'],'def last(items):\n    return items[0]','def last(items):\n    if not items:\n        return None\n    return items[-1]',[('Last not first','assert last(["a","b"])=="b"'),('Single item','assert last([7])==7'),('Empty input','assert last([]) is None')],['Handle an empty list before indexing.','Return None when there is no item.','Use index -1 otherwise.'],'python_lists','Catching every exception would hide unrelated mistakes. Handle the known empty-input condition directly.','Describe the original bug and the smallest input that exposes it.')
F(4,'Write your first assertions','Define is_even(number), returning a boolean for divisibility by 2.','An assertion states something your program expects to be true. If the expression is false, Python raises AssertionError. That is useful feedback during development.\n\nUse normal inputs, boundary values and counterexamples. A test that only repeats the example leaves many mistakes undetected.','def positive(n):\n    return n > 0\nassert positive(2) is True\nassert positive(0) is False\nprint("Two checks passed")','Two checks passed',['The first assertion checks a positive case.','The second checks the boundary zero.'],'def is_even(number):\n    pass','def is_even(number):\n    return number % 2 == 0',[('Even','assert is_even(8) is True'),('Odd','assert is_even(7) is False'),('Zero and negative','assert is_even(0) is True and is_even(-4) is True')],['% gives the remainder.','Even numbers have remainder zero after division by 2.','Return the comparison result.'],'python_operators','Do not return the strings "True" and "False". Tests need boolean values.','Add a negative odd number as a test. Explain why zero is even.')
# Week 5: errors, files and standard-library tools.
F(5,'Read a traceback from the bottom','Define parse_age(text): return int(text), or None when conversion raises ValueError.','A traceback shows the calls that led to a failure. Start at its last line to identify the exception type and message. Then inspect the referenced line in your code.\n\nCatch a specific error you know how to handle. ValueError means the type may be acceptable but the value cannot be used as requested. Do not use a broad except to hide every failure.','try:\n    age = int("eighteen")\nexcept ValueError:\n    age = None\nprint(age)','None',['Conversion fails for the supplied text.','The matching except block provides the chosen fallback.'],'def parse_age(text):\n    # Catch ValueError only.\n    pass','def parse_age(text):\n    try:\n        return int(text)\n    except ValueError:\n        return None',[('Numeric text','assert parse_age("18")==18'),('Invalid text','assert parse_age("hello") is None'),('Whitespace','assert parse_age(" 20 ")==20')],['Put int(text) in try.','Add except ValueError:.','Return None in the except block.'],'python_try_except','except: can also hide bugs such as a misspelled variable. Catch the error you intend to recover from.','Read an intentional int("x") traceback and identify its last line and source line.')
F(5,'Raise an error for an invalid request','Define withdraw(balance, amount), rejecting a negative amount or an amount greater than balance.','Sometimes your function should reject a request instead of returning an ordinary value. raise ValueError communicates a broken input rule to the caller.\n\nValidation belongs before state changes. A rejected withdrawal should not partially change data. Here we return a new balance rather than modifying an account object.','def seats(requested):\n    if requested < 1:\n        raise ValueError("Choose at least one seat")\n    return requested\nprint(seats(2))','2',['Check the input rule first.','The valid path returns normally.'],'def withdraw(balance, amount):\n    pass','def withdraw(balance, amount):\n    if amount < 0 or amount > balance:\n        raise ValueError("invalid amount")\n    return balance - amount',[('Valid withdrawal','assert withdraw(100,30)==70'),('Zero amount','assert withdraw(100,0)==100'),('Invalid request','for a in [-1,101]:\n try:\n  withdraw(100,a)\n except ValueError:\n  pass\n else:\n  raise AssertionError("Expected ValueError")')],['Combine invalid cases with or.','Raise ValueError before calculating.','Return balance-amount otherwise.'],'python_try_except','Returning zero for every invalid request makes a failure look like a successful empty balance. Use an explicit error contract.','Explain how a caller could catch the error and show a useful message.')
F(5,'Import a module instead of rewriting it','Import math and store the square root of 81 in root.','A module groups reusable Python code. import makes that module available under a name. Access its features using a dot, such as math.sqrt.\n\nThe standard library ships with Python. Third-party packages are installed separately. Prefer a well-tested library when it already solves your problem.','import math\nprint(math.sqrt(49))','7.0',['The import makes math available.','sqrt calculates the nonnegative square root.'],'# Import math and create root.','import math\nroot = math.sqrt(81)',[('Result','assert root==9'),('Module available','assert math.sqrt(16)==4')],['Write import math.','Call math.sqrt(81).','Store the result in root.'],'python_modules','Naming your own file math.py can shadow the standard library module. Use a descriptive project filename.','Look up one other math function in the documentation and try a small input.')
F(5,'Write and read a text file','Define round_trip(path,text): write UTF-8 text, then read and return it.','A file keeps data beyond a variable’s lifetime. open needs a path and mode: w writes and replaces existing content; r reads it.\n\nA with block closes the file even when an error occurs. Encoding UTF-8 supports Gujarati and other scripts. Browser runtime files are temporary: downloading code does not download files it created.','with open("demo-note.txt", "w", encoding="utf-8") as file:\n    file.write("Keep practising")\nwith open("demo-note.txt", encoding="utf-8") as file:\n    print(file.read())','Keep practising',['The first with writes text and closes the handle.','The second opens the same path for reading.'],'def round_trip(path, text):\n    pass','def round_trip(path, text):\n    with open(path,"w",encoding="utf-8") as file:\n        file.write(text)\n    with open(path,encoding="utf-8") as file:\n        return file.read()',[('Text','assert round_trip("note-a.txt","hello")=="hello"'),('Unicode','assert round_trip("note-b.txt","નમસ્તે")=="નમસ્તે"'),('Replacement','round_trip("note-c.txt","longer");assert round_trip("note-c.txt","x")=="x"')],['Use two with blocks.','Write with mode w and UTF-8.','Read and return in the second block.'],'python_file_handling','Mode w replaces existing contents. Use a when you deliberately want to append.','Add two notes using append mode on your laptop. Explain how persistence differs from the browser runtime.')
F(5,'Use paths without manual slash joining','Define filename(path_text) returning just the final filename using pathlib.Path.','A path locates a file or directory. pathlib represents a path as an object, with operations such as name, suffix and parent.\n\nWorking directory matters: a relative path starts from the program’s current directory. Read FileNotFoundError as a path problem to investigate, not proof that the file never existed.','from pathlib import Path\np = Path("notes") / "week5.txt"\nprint(p.name)\nprint(p.suffix)','week5.txt\n.txt',['The / operator joins path components.','name returns the final component; suffix returns its extension.'],'from pathlib import Path\ndef filename(path_text):\n    pass','from pathlib import Path\ndef filename(path_text):\n    return Path(path_text).name',[('Nested path','assert filename("notes/week5.txt")=="week5.txt"'),('Simple name','assert filename("readme.md")=="readme.md"'),('Spaces','assert filename("notes/my draft.txt")=="my draft.txt"')],['Create Path(path_text).','Read its .name property.','No parentheses after .name.'],'python_file_handling','A filename copied from another device may not exist here. Check the current directory and actual uploaded file location.','Print Path.cwd() on your laptop and explain where a relative notes.txt would be created.')
F(5,'Split data from the user interface','Define summarize_scores(scores) returning count and total without printing or reading input.','A command-line program has separate concerns: obtain input, calculate a result, and present it. Keep the calculation in a function that receives ordinary data.\n\nThis makes the same logic usable in a notebook, test, webpage or API. input prompts belong at the outer boundary, not inside a calculation a server needs to call.','def total(values):\n    return sum(values)\nresult = total([3, 4])\nprint(f"Total: {result}")','Total: 7',['The function only calculates.','The caller decides how to display the answer.'],'def summarize_scores(scores):\n    pass','def summarize_scores(scores):\n    return {"count":len(scores),"total":sum(scores)}',[('Normal data','assert summarize_scores([5,7])=={"count":2,"total":12}'),('Empty','assert summarize_scores([])=={"count":0,"total":0}'),('No input mutation','a=[3];summarize_scores(a);assert a==[3]')],['Use len and sum.','Return a dictionary.','Do not prompt for input inside the function.'],'python_functions','A function that asks for input cannot be easily tested with a supplied list. Accept the list as a parameter.','Write a separate display line for this result. Explain how an API could reuse the same function.')
# Week 6: common formats, database, environment and repeatable setup.
F(6,'JSON is text; a dictionary is a Python value','Define read_name(text) by parsing JSON and returning its name field.','JSON is a text format used to exchange structured data. json.loads parses JSON text into Python values. json.dumps performs the reverse conversion.\n\nA JSON string and a Python dictionary are not interchangeable. Inspect the boundary where data changes form. JSON requires double-quoted keys and has its own true, false and null spellings.','import json\nrecord = json.loads(\'{"name":"Sam"}\')\nprint(record["name"])','Sam',['The outer Python quotes hold JSON text.','loads produces a dictionary for this object.'],'import json\ndef read_name(text):\n    pass','import json\ndef read_name(text):\n    return json.loads(text)["name"]',[('Name','assert read_name(\'{"name":"Asha"}\')=="Asha"'),('Unicode','assert read_name(\'{"name":"કૃશ"}\')=="કૃશ"'),('Extra fields','assert read_name(\'{"age":18,"name":"Sam"}\')=="Sam"')],['Parse with json.loads.','Read the name key.','Return the value.'],'python_json','Calling text["name"] on the original JSON string fails. Parse it first.','Round-trip a dictionary through dumps and loads, then compare the result.')
F(6,'CSV has quoting rules','Define csv_names(text) returning name values from a CSV with a header.','CSV stores rows with fields separated by delimiters. A field can itself contain a comma when it is properly quoted. A simple split(",") does not understand that rule.\n\ncsv.DictReader uses the header row as field names. StringIO lets us practise reading text as a file without needing an upload.','import csv, io\nrows = csv.DictReader(io.StringIO("name,score\\nSam,8\\n"))\nprint([row["name"] for row in rows])',"['Sam']",['DictReader reads the header.','Each following row becomes a mapping from header name to text.'],'import csv, io\ndef csv_names(text):\n    pass','import csv, io\ndef csv_names(text):\n    return [row["name"] for row in csv.DictReader(io.StringIO(text))]',[('Ordinary row','assert csv_names("name,score\nAsha,8\n")==["Asha"]'),('Quoted comma','assert csv_names(\'name,score\n"Patel, Krish",9\n\')==["Patel, Krish"]'),('Header only','assert csv_names("name,score\n")==[]')],['Wrap text in io.StringIO.','Pass that to csv.DictReader.','Collect each row’s name value.'],'python_file_handling','CSV numbers arrive as strings. Convert them explicitly if you need numeric calculations.','Add a score field to your output and convert it to int.')
F(6,'SQL tables and parameterized values','Define stored_count(names): insert every name into SQLite and return the row count.','A relational database stores rows in tables with named columns. SQL describes operations such as CREATE TABLE, INSERT and SELECT.\n\nUse ? placeholders for values. Parameters keep a name such as O’Neil separate from SQL syntax. Table and column names are fixed in this exercise; value parameters do not replace SQL identifiers.','import sqlite3\nwith sqlite3.connect(":memory:") as db:\n    db.execute("CREATE TABLE scores(value INTEGER)")\n    db.execute("INSERT INTO scores VALUES (?)", (8,))\n    print(db.execute("SELECT COUNT(*) FROM scores").fetchone()[0])','1',['The database lives in memory for this demonstration.','The tuple (8,) supplies one parameter.','fetchone returns one result row.'],'import sqlite3\ndef stored_count(names):\n    pass','import sqlite3\ndef stored_count(names):\n    with sqlite3.connect(":memory:") as db:\n        db.execute("CREATE TABLE students(name TEXT)")\n        for name in names:\n            db.execute("INSERT INTO students VALUES (?)",(name,))\n        return db.execute("SELECT COUNT(*) FROM students").fetchone()[0]',[('Two rows','assert stored_count(["Asha","Sam"])==2'),('Apostrophe','assert stored_count(["O\'Neil"])==1'),('Empty','assert stored_count([])==0')],['Create a students table.','Loop and insert with a ? parameter.','SELECT COUNT(*) returns the count in the first result column.'],'python_mysql_getstarted','Do not insert user text into SQL using f-strings. Supply it as a parameter tuple.', 'Extend the laptop project to select names in a predictable order. Explain why the browser database disappears.',packages=['sqlite3'])
F(6,'An environment keeps project dependencies separate','Complete setup_steps as the three commands: create .venv, install requirements, then run tests.','A virtual environment gives one project its own installed packages. pip installs packages for a Python interpreter. Using python -m pip helps target the interpreter you selected.\n\nThese are terminal commands, not Python statements. In this exercise you store them as text to learn their order. On a laptop, activate the environment using the OS-specific command in the project README before installing.','steps = ["create environment", "activate it", "install requirements", "run tests"]\nprint(steps[0])','create environment',['Start with isolation.','Install the dependencies documented by the project.','Run tests before changing code.'],'setup_steps = []','setup_steps = ["python -m venv .venv", "python -m pip install -r requirements.txt", "python -m unittest"]',[('Environment command','assert setup_steps[0]=="python -m venv .venv"'),('Install command','assert setup_steps[1]=="python -m pip install -r requirements.txt"'),('Test command','assert setup_steps[2]=="python -m unittest"')],['Use a list of three strings.','Copy the command names carefully.','Remember that environment activation is an additional OS-specific step.'],'python_pip','Typing pip install inside an ordinary Python script is a syntax error. It is a terminal command.','Create a real environment on your laptop. Record python --version and the activation command in your README.')
F(6,'Git records a reviewable change','Store workflow as status, diff, add, commit in that order.','Git tracks snapshots of files in commits. The working tree contains your edits. Staging selects which edits will enter the next commit. A remote repository is a separate location such as GitHub.\n\nInspect status and diff before staging so you know what you are committing. Keep changes small enough that a reviewer can explain them. Never include private keys or real student data in a practice repository.','before_commit = ["inspect", "test", "stage", "commit"]\nprint(before_commit[-1])','commit',['Inspection comes before publishing a snapshot.','A local commit can exist without an internet connection.'],'workflow = []','workflow = ["status", "diff", "add", "commit"]',[('Workflow order','assert workflow==["status","diff","add","commit"]')],['Inspect the changed files first.','Read the content differences next.','Stage, then commit.'],'python_modules','git add is not an upload. git commit is a local snapshot. git push sends commits to a configured remote.','Make a two-line change, inspect git diff and create one local commit. Explain the change without reading a generated message.')
F(6,'Validate structured records at the boundary','Define valid_record(record): True only for a nonblank string name and integer score from 0 to 100, excluding bool.','External data can be missing fields or contain the wrong type. Validate it before calculation or storage. State the input contract in ordinary language, then translate each requirement into a check.\n\nPython bool is a subclass of int. An exact type check excludes True from an integer-only score contract. This is a deliberate rule for this exercise.','record = {"name":"Asha", "score":8}\nprint(isinstance(record["name"], str))','True',['Check types before calling type-specific methods.','A clear boundary prevents failures deeper in the program.'],'def valid_record(record):\n    pass','def valid_record(record):\n    name=record.get("name")\n    score=record.get("score")\n    return isinstance(name,str) and bool(name.strip()) and type(score) is int and 0<=score<=100',[('Valid','assert valid_record({"name":"Asha","score":80}) is True'),('Bad text','assert valid_record({"name":" ","score":80}) is False'),('Bad score','assert valid_record({"name":"A","score":True}) is False and valid_record({"name":"A","score":101}) is False')],['Use get for potentially missing keys.','Check name’s type before strip.','Use type(score) is int and validate the range.'],'python_datatypes','A truthiness check would reject the valid score zero. Separate range validation from existence.','Write two new invalid records and explain which rule rejects each.')
# Week 7: working with larger programs.
F(7,'Classes group state and behaviour','Create Counter with a value starting at 0 and an increment method adding 1.','A class defines a kind of object. An instance holds its own state. __init__ sets up that state when you create an instance. self refers to the current instance inside a method.\n\nUse a class when data and behaviour belong together. A simple calculation may still be clearer as a function. Do not turn every function into a class automatically.','class Box:\n    def __init__(self, size):\n        self.size = size\nbox = Box(3)\nprint(box.size)','3',['Box(3) creates an instance and calls __init__.','self.size stores a value on that instance.'],'class Counter:\n    def __init__(self):\n        pass\n    def increment(self):\n        pass','class Counter:\n    def __init__(self):\n        self.value = 0\n    def increment(self):\n        self.value += 1',[('Initial state','c=Counter();assert c.value==0'),('Increment','c=Counter();c.increment();assert c.value==1'),('Separate instances','a=Counter();b=Counter();a.increment();assert b.value==0')],['Set self.value in __init__.','Increment self.value in the method.','Each new Counter needs its own value.'],'python_classes','Putting a shared mutable list on the class can share it across instances. Initialize per-object mutable state in __init__.','Create two counters and increment only one. Explain why their values differ.')
F(7,'Composition keeps objects understandable','Define Team with a members list supplied at creation; copy it and return its length from size().','Composition means building an object using other values or objects. A Team contains members. This often models a relationship more directly than inheritance.\n\nWhen a caller owns a mutable list, decide whether your object shares it or copies it. Here the contract asks for a copy so later caller changes do not change the team.','original = ["Asha"]\ncopy = list(original)\ncopy.append("Sam")\nprint(len(original))','1',['list(original) creates a separate list.','Appending to the copy leaves the original length unchanged.'],'class Team:\n    def __init__(self, members):\n        pass\n    def size(self):\n        pass','class Team:\n    def __init__(self, members):\n        self.members = list(members)\n    def size(self):\n        return len(self.members)',[('Count','assert Team(["A","B"]).size()==2'),('Empty','assert Team([]).size()==0'),('Copy boundary','a=["A"];t=Team(a);a.append("B");assert t.size()==1')],['Copy with list(members).','Store the copy on self.','Return len(self.members).'],'python_classes','self.members=members shares the same list. That may be valid in another design, but it breaks this contract.','Explain the difference between shallow copying a list and copying nested objects inside it.')
F(7,'Read nested API data carefully','Define city(payload) returning payload["user"]["city"] or "Unknown" when user or city is missing. Assume user is a dictionary when present.','An API response often nests dictionaries and lists. Sketch the structure before writing the lookup. Validate types at the boundary, then navigate fields according to that contract.\n\nThis exercise uses a local fixture so it works without a live service. Real requests also need timeouts, status checks and handling for invalid JSON.','payload = {"user":{"name":"Asha"}}\nprint(payload["user"]["name"])','Asha',['First select the user dictionary.','Then select its name field.'],'def city(payload):\n    pass','def city(payload):\n    return payload.get("user",{}).get("city","Unknown")',[('Nested value','assert city({"user":{"city":"Ahmedabad"}})=="Ahmedabad"'),('Missing user','assert city({})=="Unknown"'),('Missing city','assert city({"user":{}})=="Unknown"')],['Use get for the user with {} as fallback.','Call get again for city.','Use Unknown as the text fallback.'],'python_dictionaries','A fallback does not validate a wrong type. If user were a list, this code would need a separate validation rule.','Draw a nested payload with two users. Explain where you would loop instead of using one key.')
F(7,'Search a sequence and describe the cost','Define first_index(items,target), returning the first matching index or -1.','A linear search examines items from left to right. enumerate supplies both an index and value. Return as soon as you find the first match.\n\nIf there are n items, the worst case examines n items: O(n). This describes how work grows, not an exact number of seconds. Learn to explain this before memorizing algorithm names.','for index, value in enumerate(["a", "b"]):\n    print(index, value)','0 a\n1 b',['enumerate pairs positions with values.','Indexes start at zero.'],'def first_index(items, target):\n    pass','def first_index(items, target):\n    for i,value in enumerate(items):\n        if value==target:\n            return i\n    return -1',[('First match','assert first_index([3,5,3],3)==0'),('Later match','assert first_index([3,5],5)==1'),('Missing','assert first_index([],3)==-1 and first_index([1],2)==-1')],['Use enumerate in the loop.','Return i when the value matches.','Return -1 after the loop.'],'python_for_loops','Returning -1 inside the loop gives up after the first non-match. Indentation changes the algorithm.','Explain the best and worst case. Compare when a dictionary lookup would be more appropriate.')
F(7,'Sort with a key without changing input','Define ranked(records), returning a new list sorted by score descending.','sorted returns a new list. A key function tells it which value to compare. lambda can express a small one-expression function at the point of use.\n\nA list’s .sort method changes that list and returns None. Choose deliberately between an in-place operation and a returned result.','records = [{"name":"A","score":2},{"name":"B","score":5}]\nprint(sorted(records, key=lambda r:r["score"])[0]["name"])','A',['The key reads each score.','Ascending order puts the smaller score first.'],'def ranked(records):\n    pass','def ranked(records):\n    return sorted(records,key=lambda r:r["score"],reverse=True)',[('Descending order','assert [r["score"] for r in ranked([{"score":2},{"score":5}])]==[5,2]'),('Empty','assert ranked([])==[]'),('Input preserved','a=[{"score":2},{"score":5}];ranked(a);assert a[0]["score"]==2')],['Use sorted rather than .sort.','The key should read score.','Set reverse=True.'],'python_lambda','A long lambda is difficult to read. Use a named function when the decision needs multiple steps.','Add two equal scores and inspect their relative order. Explain Python’s stable sorting behaviour.')
F(7,'Build a module with a clear interface','Define slug_words(text) as a reusable helper that strips whitespace, lowercases words and joins them with hyphens.','A module is a Python file with a focused purpose. Expose small functions with clear names and contracts. Keep interactive prompts in a separate CLI layer.\n\nFor a real laptop module, use an if __name__ == "__main__" guard around demonstration code. Importing a helper should not unexpectedly ask questions or start a server.','def join_words(words):\n    return "-".join(words)\nprint(join_words(["study", "notes"]))','study-notes',['join combines strings with a separator.','The helper returns a value the caller can reuse.'],'def slug_words(text):\n    pass','def slug_words(text):\n    return "-".join(text.lower().split())',[('Whitespace','assert slug_words("  My Notes ")=="my-notes"'),('Empty','assert slug_words("")==""'),('Repeated spaces','assert slug_words("A   B")=="a-b"')],['lower normalizes case.','split without an argument handles repeated whitespace.','Join the words with a hyphen.'],'python_modules','Do not call this a complete URL sanitizer. Real URLs need additional rules and validation.','Put the helper in a file, import it from another file, and confirm that importing does not run a prompt.')
# Week 8: tests, maintainability and transfer.
F(8,'List comprehensions after you understand loops','Define squares(numbers), returning a new list of squared values.','A list comprehension is a compact way to build a new list from an iterable. Read it as: calculate this expression for every item.\n\nStart by writing the ordinary loop if the expression is confusing. A shorter program is not automatically a clearer one. Avoid deeply nested comprehensions when a few named steps would explain the logic.','doubled = [n * 2 for n in [1, 2, 3]]\nprint(doubled)','[2, 4, 6]',['The expression n*2 produces each new item.','The for part supplies values of n.'],'def squares(numbers):\n    pass','def squares(numbers):\n    return [n*n for n in numbers]',[('Values','assert squares([2,-3,0])==[4,9,0]'),('Empty','assert squares([])==[]'),('Original','a=[2];squares(a);assert a==[2]')],['Use brackets for the new list.','Write n*n before for.','Return the new list.'],'python_lists','A comprehension used only for side effects makes intent harder to read. Use a loop for actions.','Rewrite your solution as a normal loop and compare readability.')
F(8,'Generators produce one result at a time','Define countdown(n) yielding n down to 1; nonpositive n yields nothing.','A generator uses yield to produce a value and pause. The next iteration resumes from that point. It avoids creating a full list when you only need one item at a time.\n\nGenerators are consumed as you iterate. To repeat the sequence, create a new generator. They are useful for processing a stream or large file without keeping every result in memory.','def two_values():\n    yield 10\n    yield 20\nprint(list(two_values()))','[10, 20]',['The function returns a generator when called.','list consumes its yielded values for display.'],'def countdown(n):\n    # Use yield in a terminating loop.\n    return iter([])','def countdown(n):\n    while n>0:\n        yield n\n        n-=1',[('Sequence','assert list(countdown(3))==[3,2,1]'),('Empty','assert list(countdown(0))==[]'),('Lazy iterator','g=countdown(2);assert iter(g) is g and next(g)==2')],['Loop while n>0.','Yield n before reducing it.','Decrease n inside the loop.'],'python_iterators','return ends the generator; yield pauses it. Replacing yield with return loses the sequence.','Consume one item with next and then the remainder with list. Explain why the first item is absent from the remainder.')
F(8,'Type hints document a contract','Define join_name(first: str,last: str) -> str returning stripped names separated by one space.','Type hints communicate expected types to people and checking tools. Python normally does not enforce these hints at runtime. You still need validation at external boundaries.\n\nUse hints to make an interface easier to understand. Prefer a small, honest contract over annotations that claim more than your implementation guarantees.','def increase(value: int) -> int:\n    return value + 1\nprint(increase(4))','5',['The annotation describes the intended input.','The body still performs ordinary Python arithmetic.'],'def join_name(first: str, last: str) -> str:\n    pass','def join_name(first: str, last: str) -> str:\n    return first.strip()+" "+last.strip()',[('Names','assert join_name("Asha","Patel")=="Asha Patel"'),('Whitespace','assert join_name(" Asha "," Patel ")=="Asha Patel"'),('Return type','assert isinstance(join_name("A","B"),str)')],['Strip each input.','Join with one space.','Keep the supplied annotations.'],'python_functions','Annotations alone do not reject a number supplied as first. Decide where runtime validation belongs.','Add a docstring stating assumptions and one example call. Ask another student whether the contract is clear.')
F(8,'Regression tests protect a fixed bug','Fix average(values), returning None for empty input and the arithmetic mean otherwise.','A regression test captures a bug so it does not quietly return later. First produce the smallest failing case. Fix the code, then keep that case alongside normal examples.\n\nDo not write a test that simply repeats your implementation. State an expected result you can calculate independently. For [2,4], the mean should be three.','values = [2, 4]\nexpected = 3\nassert sum(values)/len(values) == expected\nprint("Mean checked")','Mean checked',['The expected result is reasoned about separately.','The assertion compares the implementation’s result with it.'],'def average(values):\n    return sum(values) / len(values)','def average(values):\n    if not values:\n        return None\n    return sum(values)/len(values)',[('Normal','assert average([2,4])==3'),('Regression: empty','assert average([]) is None'),('Real zero','assert average([-1,1])==0')],['An empty input causes division by zero.','Return None before dividing.','Do not confuse no data with a real mean of zero.'],'python_try_except','Changing the test to accept the broken answer does not fix the bug. Recheck the intended contract.','Write a short bug report with input, expected result, actual result and your fix.')
F(8,'Use structured information for debugging','Define audit(action,item_id), returning an event dictionary with those fields and status="ok".','Useful logs describe events with consistent fields. A developer can then connect a request, action and result. Printing an unexplained number is much less helpful.\n\nThis exercise builds an event record rather than configuring logging. In a project, use Python’s logging module and choose an appropriate level. Never put passwords or private messages in routine logs.','event = {"action":"save", "item_id":7, "status":"ok"}\nprint(event["action"], event["status"])','save ok',['The field names explain the values.','A stable structure is easier to search and test.'],'def audit(action, item_id):\n    pass','def audit(action, item_id):\n    return {"action":action,"item_id":item_id,"status":"ok"}',[('Action','assert audit("save",7)["action"]=="save"'),('Identifier','assert audit("delete",0)["item_id"]==0'),('Stable fields','assert set(audit("read",1))=={"action","item_id","status"}')],['Return a dictionary.','Keep the supplied action and item_id.','Add the fixed status ok.'],'python_dictionaries','A log entry is not proof that an operation succeeded. Write it after checking the actual result.','Replace a print in your laptop project with logging.info and explain which data should be excluded.')
F(8,'Review code before sharing it','Define ready(checks) that is True only when tests, readme and no_secrets are explicitly True.','A code review asks whether the change solves the stated problem, is understandable, and has evidence. A README should let someone start from a clean folder and reproduce your result.\n\nA checklist is a reminder, not an automated security or quality guarantee. Let another person run your project and ask for one small change you did not prepare for.','checks = {"tests":True, "readme":False}\nprint(checks.get("tests") is True)','True',['A missing requirement should not count as complete.','Explicit booleans make this small contract predictable.'],'def ready(checks):\n    pass','def ready(checks):\n    return all(checks.get(key) is True for key in ("tests","readme","no_secrets"))',[('Complete','assert ready({"tests":True,"readme":True,"no_secrets":True}) is True'),('Missing','assert ready({"tests":True}) is False'),('Not a boolean','assert ready({"tests":"yes","readme":True,"no_secrets":True}) is False')],['Read every required key.','Require each value to be True.','all combines the checks.'],'python_booleans','A self-reported checklist cannot replace an independent review. Show the evidence behind each check.','Ask someone to run your README instructions and record where they get stuck.')
# One orientation exercise before each applied week.
F(9,'Understand the page before styling it','Create an HTML page with main, h1 and a paragraph explaining your first Python project.','HTML describes the structure and meaning of a webpage. CSS controls appearance. JavaScript adds browser behaviour. Python usually runs on the server or in a special browser runtime such as this notebook.\n\nStart with content people can read. A main landmark and a clear heading help navigation. Styling comes after the page has a sensible structure.','<main>\n  <h1>My first project</h1>\n  <p>A small notes tool.</p>\n</main>','A heading and a paragraph',['main identifies the principal page content.','h1 names the page; p explains it.'],'<!doctype html>\n<html lang="en"><body>\n<!-- Add main, h1 and p. -->\n</body></html>','<!doctype html><html lang="en"><body><main><h1>My Python project</h1><p>I built a notes tool.</p></main></body></html>',[],['Start with main.','Place h1 and p inside it.','Write meaningful text in both.'],'python_intro','A paragraph styled with a large font is not automatically a heading. Use the element that matches the meaning.','Explain which part of a full app runs in the browser and which part runs on the server.',language='html')
LESSONS[-1]['tests']=[dict(label='Main heading',selector='main h1',kind='text'),dict(label='Project description',selector='main p',kind='text')]
F(10,'Trace a request and response','Define response(body,status=200) returning a dictionary with status and body.','An HTTP client sends a method, URL, headers and sometimes a body. A server handles the request and returns a status, headers and body. JSON is a common body format.\n\nFastAPI maps paths and methods to Python functions. The function below models a response for practice; the downloadable project starts a real server. First understand the flow before adding databases or accounts.','request = {"method":"GET", "path":"/tasks"}\nprint(request["method"], request["path"])','GET /tasks',['GET asks to read a resource.','The path identifies the resource inside the service.'],'def response(body, status=200):\n    pass','def response(body, status=200):\n    return {"status":status,"body":body}',[('Default','assert response([])=={"status":200,"body":[]}'),('Creation','assert response({"id":1},201)["status"]==201'),('Error','assert response({"error":"missing"},404)["body"]=={"error":"missing"}')],['Return both pieces of information.','Keep body unchanged.','Use the default status unless overridden.'],'python_json','A JSON error message with status 200 can look like a successful request to clients. Communicate failure consistently.','In the project /docs page, send GET and POST requests and describe each response field.')
F(11,'Model loading, empty, success and error states','Define view_state(loading,error,items), returning loading, error, empty or ready in that priority order.','A webpage must tell a user what is happening while a request is pending, when it fails, and when it succeeds with no data. These are distinct states.\n\nJavaScript fetch returns a promise. Await the response, check response.ok, then parse JSON. A network failure and an HTTP error need handling. The project kit contains that browser code.','states = ["loading", "error", "empty", "ready"]\nprint(states[-1])','ready',['A successful request can still have no items.','An error should not leave an old success message on screen.'],'def view_state(loading, error, items):\n    pass','def view_state(loading, error, items):\n    if loading: return "loading"\n    if error: return "error"\n    return "ready" if items else "empty"',[('Loading priority','assert view_state(True,True,[])=="loading"'),('Error','assert view_state(False,True,[1])=="error"'),('Empty and ready','assert view_state(False,False,[])=="empty" and view_state(False,False,[1])=="ready"')],['Check loading first.','Then check error.','Distinguish empty from nonempty items.'],'python_conditions','Updating the DOM with innerHTML for arbitrary server text can interpret markup. Use textContent for plain text.','Stop your local API while the page is open. Confirm that the UI shows an error instead of an endless spinner.')
F(12,'Separate a local demo from a deployable service','Define missing_settings(config) returning missing nonblank APP_MODE and DATABASE_URL keys in that order.','Deployment means running your program in another environment. That environment needs a start command, dependencies, configuration and a way to observe failures.\n\nA local in-memory demo resets when the process restarts. Before calling it a persistent service, add an actual database and test restart behaviour. For this exercise use fake configuration values only.','required = ["APP_MODE", "DATABASE_URL"]\nprint(len(required))','2',['Required configuration should be explicit.','Check it early so a deployment fails with a useful explanation.'],'def missing_settings(config):\n    pass','def missing_settings(config):\n    return [k for k in ("APP_MODE","DATABASE_URL") if not isinstance(config.get(k),str) or not config[k].strip()]',[('Missing both','assert missing_settings({})==["APP_MODE","DATABASE_URL"]'),('One blank','assert missing_settings({"APP_MODE":"demo","DATABASE_URL":" "})==["DATABASE_URL"]'),('Complete','assert missing_settings({"APP_MODE":"demo","DATABASE_URL":"sqlite:///demo.db"})==[]')],['Loop through the required names in order.','Treat missing, non-text and blank values as missing.','Return their names, not secret values.'],'python_dictionaries','Putting a credential in frontend JavaScript exposes it to visitors. Keep server configuration on the server.','Write deployment instructions for the sample app and list which demo limitations remain.')
F(13,'Features, labels and a baseline','Define majority(labels), returning the most frequent label; break ties alphabetically and return None for no labels.','A feature is information a model can use as input. A label is the target you want it to predict. Training examples connect inputs with known labels.\n\nBefore training, compare with a simple baseline. Always predicting the most common label can already score highly on an imbalanced dataset. A more complex model must justify its added complexity.','labels = ["billing", "billing", "technical"]\nprint(labels.count("billing"))','2',['There are two billing examples.','A majority baseline would always choose billing for this training set.'],'def majority(labels):\n    pass','def majority(labels):\n    if not labels: return None\n    counts={label:labels.count(label) for label in set(labels)}\n    return sorted(counts,key=lambda label:(-counts[label],label))[0]',[('Majority','assert majority(["b","a","b"])=="b"'),('Tie','assert majority(["b","a"])=="a"'),('Empty','assert majority([]) is None')],['Count each distinct label.','Sort by negative count, then the label.','Handle the empty list first.'],'python_dictionaries','Training accuracy alone does not show how a model behaves on unseen examples. Hold out data before fitting.','Calculate the majority baseline accuracy on a small labelled dataset by hand.')
F(14,'Understand a text pipeline before fitting it','Define tokens(text) returning sorted unique lowercase whitespace-separated words.','A text classifier cannot directly multiply words as numbers. A vectorizer converts text into numeric features. TF-IDF gives a token a weight based on its frequency in a document and across the training collection.\n\nThe small tokenizer below is a preparation exercise, not a complete TF-IDF vectorizer. The next lesson uses scikit-learn’s tested implementation inside a pipeline with logistic regression.','text = "Python python web"\nprint(sorted(set(text.lower().split())))',"['python', 'web']",['Normalize case before counting distinct words.','A real vectorizer has documented tokenization rules beyond this simple split.'],'def tokens(text):\n    pass','def tokens(text):\n    return sorted(set(text.lower().split()))',[('Duplicates','assert tokens("AI ai Python")==["ai","python"]'),('Empty','assert tokens(" ")==[]'),('Whitespace','assert tokens("web\npython")==["python","web"]')],['Lowercase first.','Split on whitespace and deduplicate.','Sort for predictable output.'],'python_strings','Fitting the vectorizer on all data before a split leaks test information. Fit the entire pipeline on training data.','Explain where vocabulary learning happens and why a new word may have no learned feature.')
F(15,'Retrieval finds evidence before an answer','Define overlap(query,text), counting distinct shared lowercase whitespace-separated words.','A retrieval system searches stored information for evidence related to a query. A lexical system matches words; it may miss a paraphrase that uses different words.\n\nGeneration is a separate step that writes new text. Start by making retrieval measurable: save test queries, expected source IDs and no-match examples. Add an LLM only when you can evaluate whether it improves the task.','query = set("python lists".split())\nnote = set("lists keep order".split())\nprint(len(query & note))','1',['The ampersand finds the shared set members.','Only lists appears in both sets.'],'def overlap(query, text):\n    pass','def overlap(query, text):\n    return len(set(query.lower().split()) & set(text.lower().split()))',[('Overlap','assert overlap("python lists","lists python order")==2'),('No match','assert overlap("weather","python")==0'),('No duplicate counting','assert overlap("AI AI","ai")==1')],['Create two lowercase word sets.','Intersect them with &.','Return the size of the intersection.'],'python_sets','A matching word does not prove a source answers the question. Inspect the retrieved evidence and test misleading matches.','Write one paraphrase that this lexical matcher misses. Propose a test before trying an embedding model.')
F(16,'Turn a project into evidence for an interview','Define portfolio_files(files) returning True when README.md, app.py and test_app.py are all present.','An internship reviewer needs evidence that you can understand and change working software. A useful project has a clear problem, a small scope, setup instructions, tests and honest limitations.\n\nPrepare a short demo and a change request you have not rehearsed. Explain how data moves through the app, one bug you fixed, and one tradeoff. File presence is only a small readiness reminder; the files still need meaningful content.','files = {"README.md", "app.py"}\nprint("README.md" in files)','True',['The README is a starting point for another developer.','A project must also run correctly from those instructions.'],'def portfolio_files(files):\n    pass','def portfolio_files(files):\n    return {"README.md","app.py","test_app.py"}.issubset(set(files))',[('Complete','assert portfolio_files(["README.md","app.py","test_app.py"]) is True'),('Missing tests','assert portfolio_files(["README.md","app.py"]) is False'),('Extra files','assert portfolio_files(["README.md","app.py","test_app.py","notes.txt"]) is True')],['Build a set of required names.','Convert the supplied names to a set.','Use issubset.'],'python_sets','Counting certificates or files cannot demonstrate understanding. Be ready to explain and change the actual code.','Record a two-minute demo, then implement one small new requirement without reading the reference.')

