# Use repr for embedded data so newlines remain valid Python string literals.
for lesson in LESSONS:
 if lesson['id']=='f06-l2':
  fixtures=[('Ordinary row','name,score\nAsha,8\n',['Asha']),('Quoted comma','name,score\n"Patel, Krish",9\n',['Patel, Krish']),('Header only','name,score\n',[])]
  lesson['tests']=[{'label':label,'code':f'assert csv_names({text!r})=={expected!r}'} for label,text,expected in fixtures]
